-- GENERATED by hyde-db from schema.prisma. Do not edit by hand.
-- Recreates schema redacted with column-filtered views and grants role redacted_reader
-- read access to exactly those views. Run AFTER `prisma migrate deploy`.
-- The whole script is one transaction; the final check aborts it if the role
-- could read anything outside the views.

BEGIN;
SET LOCAL client_min_messages = warning;
SET LOCAL lock_timeout = '60s';
SET LOCAL jit = off;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'redacted_reader') THEN
    CREATE ROLE "redacted_reader" NOLOGIN;
    PERFORM set_config('hyde_db.created_reader', 'on', true);
  END IF;
END $$;

-- Refuse to drop a schema that hyde-db did not create.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'redacted'
             AND NOT (coalesce(obj_description(oid, 'pg_namespace'), '') = 'Generated by hyde-db'
                      OR starts_with(coalesce(obj_description(oid, 'pg_namespace'), ''), 'Generated by hyde-db.'))) THEN
    RAISE EXCEPTION 'hyde-db: schema redacted exists but was not created by hyde-db (its comment lacks the "Generated by hyde-db" marker); refusing to drop it. Rename or drop that schema yourself, or set the generator config "schema" to an unused name.';
  END IF;
END $$;

-- Refuse to drop objects outside schema redacted that depend on its views.
DO $$
DECLARE
  dependents text;
BEGIN
  SELECT string_agg(DISTINCT format('%s %s', i.type, i.identity) COLLATE "C", ', ' ORDER BY format('%s %s', i.type, i.identity) COLLATE "C") INTO dependents
  FROM (SELECT 'pg_class'::regclass AS classid, c.oid FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'redacted'
        UNION ALL SELECT 'pg_type'::regclass, t.oid FROM pg_type t JOIN pg_namespace s ON s.oid = t.typnamespace WHERE s.nspname = 'redacted') v
    JOIN pg_depend d ON d.refclassid = v.classid AND d.refobjid = v.oid
    LEFT JOIN pg_rewrite w ON d.classid = 'pg_rewrite'::regclass AND w.oid = d.objid
    LEFT JOIN pg_trigger tg ON d.classid = 'pg_trigger'::regclass AND tg.oid = d.objid
    LEFT JOIN pg_policy po ON d.classid = 'pg_policy'::regclass AND po.oid = d.objid
    LEFT JOIN pg_attrdef ad ON d.classid = 'pg_attrdef'::regclass AND ad.oid = d.objid
    CROSS JOIN LATERAL pg_identify_object(CASE WHEN w.oid IS NULL THEN d.classid ELSE 'pg_class'::regclass END, coalesce(w.ev_class, d.objid), CASE WHEN w.oid IS NULL THEN d.objsubid ELSE 0 END) i
    CROSS JOIN LATERAL (SELECT coalesce((SELECT quote_ident(n.nspname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.oid = coalesce(w.ev_class, tg.tgrelid, po.polrelid, ad.adrelid)), i.schema) AS schema) h
  WHERE d.deptype IN ('n', 'a')
    AND h.schema IS DISTINCT FROM quote_ident('redacted')
    AND coalesce(h.schema, '') !~ '^pg_(toast_)?temp_'
    AND NOT EXISTS (SELECT 1 FROM pg_depend o CROSS JOIN LATERAL pg_identify_object(o.refclassid, o.refobjid, 0) oi WHERE o.classid = d.classid AND o.objid = d.objid AND oi.schema ~ '^pg_(toast_)?temp_');
  IF dependents IS NOT NULL THEN
    RAISE EXCEPTION 'hyde-db: objects outside schema redacted depend on its views: %; refusing to drop them with the schema. Drop them before the deploy, and create them again after it if you still need them.', dependents;
  END IF;
END $$;

DROP SCHEMA IF EXISTS "redacted" CASCADE;
CREATE SCHEMA "redacted";
COMMENT ON SCHEMA "redacted" IS 'Generated by hyde-db. Read-only views with sensitive columns removed. Recreated on every deploy.';

CREATE VIEW "redacted"."products" AS SELECT
  "id",
  "title",
  "price_cents",
  "tags",
  "status",
  "category_id"
FROM "public"."products";
COMMENT ON VIEW "redacted"."products" IS 'Product catalogue entry.';
COMMENT ON COLUMN "redacted"."products"."price_cents" IS 'Price in cents';

CREATE VIEW "redacted"."Category" AS SELECT
  "id",
  "label",
  "support_email"
FROM "public"."Category";
COMMENT ON COLUMN "redacted"."Category"."label" IS 'Display label';
COMMENT ON COLUMN "redacted"."Category"."support_email" IS 'Public support inbox';

-- Privileges: nothing but SELECT on the views in redacted. Privileges elsewhere are
-- not revoked here: the final check refuses them and prints the statements that remove them.
GRANT USAGE ON SCHEMA "redacted" TO "redacted_reader";
GRANT SELECT ON ALL TABLES IN SCHEMA "redacted" TO "redacted_reader";

-- Defence in depth for the session itself.
ALTER ROLE "redacted_reader" SET default_transaction_read_only = on;
ALTER ROLE "redacted_reader" SET statement_timeout = '15s';
ALTER ROLE "redacted_reader" SET search_path = "redacted";

-- Safety check, in this order: abort if the role
--   has SUPERUSER, CREATEDB, CREATEROLE, REPLICATION or BYPASSRLS (first: a superuser passes
--     every privilege test below);
--   owns any object in this database other than its own temporary objects and large objects, or
--     any database (an owner can grant itself access again, so no REVOKE can fix it);
--   is a member of another role (inherited privileges have no grant of their own to revoke);
--   can create schemas in this database;
--   holds privileges on pg_catalog, information_schema or pg_toast objects beyond their initial
--     ones;
--   holds any privilege on a relation outside the views schema, or can use a foreign server;
--   can execute a SECURITY DEFINER function or use a sequence;
--   gains privileges on objects created later through other roles' default privileges (before
--     the schema check: this script creates the views schema under them);
--   can create objects in any schema;
--   has lo_compat_privileges on, which turns off privilege checks on large objects;
--   can read large objects of other roles;
--   holds SET or ALTER SYSTEM on a configuration parameter (PostgreSQL 15 and later).
-- Each abort prints the statements that fix it, to be run by an administrator, as one
-- transaction when there are several, and says who must run them when the deploying role
-- cannot.
DO $$
DECLARE
  leaks text;
  fixes text;
  runner text;
BEGIN
  SELECT concat_ws(', ', CASE WHEN r.rolsuper THEN 'SUPERUSER' END, CASE WHEN r.rolcreatedb THEN 'CREATEDB' END, CASE WHEN r.rolcreaterole THEN 'CREATEROLE' END, CASE WHEN r.rolreplication THEN 'REPLICATION' END, CASE WHEN r.rolbypassrls THEN 'BYPASSRLS' END),
         format('ALTER ROLE %I %s;', r.rolname, concat_ws(' ', CASE WHEN r.rolsuper THEN 'NOSUPERUSER' END, CASE WHEN r.rolcreatedb THEN 'NOCREATEDB' END, CASE WHEN r.rolcreaterole THEN 'NOCREATEROLE' END, CASE WHEN r.rolreplication THEN 'NOREPLICATION' END, CASE WHEN r.rolbypassrls THEN 'NOBYPASSRLS' END))
    INTO leaks, fixes
  FROM pg_roles r
  WHERE r.rolname = 'redacted_reader';
  IF leaks <> '' THEN
    RAISE EXCEPTION 'hyde-db: role redacted_reader has attributes it must not have: %. Fix: %', leaks, concat(CASE WHEN fixes LIKE '%; %' AND fixes NOT LIKE 'ALTER SYSTEM %' THEN 'BEGIN; ' || fixes || ' COMMIT;' ELSE fixes END, CASE WHEN fixes LIKE '%SET ROLE %' THEN ' -- run as a superuser' END);
  END IF;
  -- The joins on pg_roles below always find the role: this transaction created it above if missing.
  SELECT string_agg(format('%s %s', i.type, i.identity), ', ' ORDER BY i.type COLLATE "C", i.identity COLLATE "C") INTO leaks
  FROM pg_roles r
    JOIN pg_shdepend s ON s.refclassid = 'pg_authid'::regclass AND s.refobjid = r.oid AND s.deptype = 'o'
      AND s.dbid IN (0, (SELECT d.oid FROM pg_database d WHERE d.datname = current_database()))
    CROSS JOIN LATERAL pg_identify_object(s.classid, s.objid, s.objsubid) i
  WHERE r.rolname = 'redacted_reader'
    AND s.classid NOT IN ('pg_largeobject'::regclass, 'pg_default_acl'::regclass, 'pg_user_mapping'::regclass)
    AND coalesce(i.schema, '') !~ '^pg_(toast_)?temp_';
  IF leaks IS NOT NULL THEN
    RAISE EXCEPTION 'hyde-db: role redacted_reader owns objects it must not own: %. Fix: REASSIGN OWNED BY % TO CURRENT_USER; -- run as an administrator', leaks, quote_ident('redacted_reader');
  END IF;
  SELECT string_agg(format('%I', g.rolname), ', ' ORDER BY g.rolname),
         string_agg((SELECT string_agg(format('REVOKE %I FROM %I%s CASCADE;', g.rolname, r.rolname, CASE WHEN current_setting('server_version_num')::int >= 160000 THEN format(' GRANTED BY %s', m.grantor::regrole) END), ' ' ORDER BY m.grantor) FROM pg_auth_members m WHERE m.roleid = g.oid AND m.member = r.oid), ' ' ORDER BY g.rolname)
    INTO leaks, fixes
  FROM pg_roles g CROSS JOIN pg_roles r
  WHERE r.rolname = 'redacted_reader'
    AND EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = g.oid AND m.member = r.oid);
  IF leaks IS NOT NULL THEN
    RAISE EXCEPTION 'hyde-db: role redacted_reader must not be a member of other roles: %. Fix: %', leaks, concat(CASE WHEN fixes LIKE '%; %' AND fixes NOT LIKE 'ALTER SYSTEM %' THEN 'BEGIN; ' || fixes || ' COMMIT;' ELSE fixes END, CASE WHEN fixes LIKE '%SET ROLE %' THEN ' -- run as a superuser' END);
  END IF;
  SELECT string_agg(format('%I', d.datname), ', '), string_agg(concat_ws(' ', (SELECT string_agg(format('%sSET ROLE %s; %s RESET ROLE;%s', (SELECT string_agg(concat(CASE WHEN k.lender <> d.datdba THEN format('SET ROLE %s; ', k.lender::regrole) END, format('GRANT %s ON %s TO %s WITH GRANT OPTION;', k.items, format('DATABASE %I', d.datname), t.grantor::regrole), CASE WHEN k.lender <> d.datdba THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) AS items FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(d.datacl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(d.datacl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(d.datacl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, d.datdba, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), d.datdba) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('CREATE') AND NOT EXISTS (SELECT 1 FROM aclexplode(d.datacl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k) || ' ', t.grantor::regrole, CASE WHEN t.grantor <> r.oid THEN (SELECT format('REVOKE %s ON %s FROM %s CASCADE;', string_agg(DISTINCT x.privilege_type, ', ' ORDER BY x.privilege_type), format('DATABASE %I', d.datname), t.grantees) FROM aclexplode(d.datacl) x WHERE x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('CREATE') HAVING count(*) > 0) END, ' ' || (SELECT string_agg(concat(CASE WHEN k.lender <> d.datdba THEN format('SET ROLE %s; ', k.lender::regrole) END, concat_ws(' ', CASE WHEN k.held IS NOT NULL THEN format('REVOKE GRANT OPTION FOR %s ON %s FROM %s CASCADE;', k.held, format('DATABASE %I', d.datname), t.grantor::regrole) END, CASE WHEN k.unheld IS NOT NULL THEN format('REVOKE %s ON %s FROM %s CASCADE;', k.unheld, format('DATABASE %I', d.datname), t.grantor::regrole) END), CASE WHEN k.lender <> d.datdba THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE o.held) AS held, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE NOT o.held) AS unheld FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(d.datacl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(d.datacl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(d.datacl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, d.datdba, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), d.datdba) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('CREATE') AND NOT EXISTS (SELECT 1 FROM aclexplode(d.datacl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k)), ' ' ORDER BY t.grantor) FROM (SELECT g.grantor, string_agg(CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END, ', ' ORDER BY g.grantee) AS grantees FROM (SELECT DISTINCT a.grantor, a.grantee FROM aclexplode(d.datacl) a WHERE a.privilege_type IN ('CREATE') AND a.grantee IN (0, r.oid) AND a.grantor <> d.datdba AND a.grantor <> r.oid) g GROUP BY g.grantor) t), 'REVOKE ' || format('CREATE ON DATABASE %I', d.datname) || ' FROM ' || nullif(concat_ws(', ', CASE WHEN EXISTS (SELECT 1 FROM aclexplode(d.datacl) a WHERE a.privilege_type IN ('CREATE') AND a.grantee = 0 AND a.grantor = d.datdba) THEN 'PUBLIC' END, CASE WHEN r.oid = d.datdba OR EXISTS (SELECT 1 FROM aclexplode(d.datacl) a WHERE a.privilege_type IN ('CREATE') AND a.grantee = r.oid AND a.grantor = d.datdba) THEN quote_ident(r.rolname) END), '') || ' CASCADE;'), ' '),
         CASE WHEN bool_and(pg_has_role(CASE WHEN d.datdba = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE d.datdba END, 'USAGE')) IS NOT FALSE THEN NULL WHEN count(DISTINCT CASE WHEN d.datdba = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE d.datdba END) = 1 THEN format(' -- run as %s or a superuser', min(CASE WHEN d.datdba = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE d.datdba END)::regrole) ELSE ' -- run as a superuser' END
    INTO leaks, fixes, runner
  FROM pg_database d CROSS JOIN pg_roles r
  WHERE r.rolname = 'redacted_reader' AND d.datname = current_database()
    AND has_database_privilege(r.oid, d.oid, 'CREATE');
  IF leaks IS NOT NULL THEN
    RAISE EXCEPTION 'hyde-db: role redacted_reader can create schemas in database %. Fix: %', leaks, concat(CASE WHEN fixes LIKE '%; %' AND fixes NOT LIKE 'ALTER SYSTEM %' THEN 'BEGIN; ' || fixes || ' COMMIT;' ELSE fixes END, CASE WHEN fixes LIKE '%SET ROLE %' THEN ' -- run as a superuser' ELSE runner END);
  END IF;
  WITH e AS (SELECT ce.object, ce.target, ce.relid, ce.attnum, ce.privilege_type, ce.privilege, ce.grantee, ce.grantor, ce.owner, ce.on_column,
           ce.grantor <> ce.owner AND NOT EXISTS (SELECT 1 FROM aclexplode(ce.own_acl) h WHERE h.grantee = ce.grantor AND h.privilege_type = ce.privilege_type AND h.is_grantable) AS lost, b.lender,
           EXISTS (SELECT 1 FROM aclexplode(ce.lender_acl) h WHERE h.grantee = ce.grantor AND h.grantor = b.lender AND h.privilege_type = ce.privilege_type) AS held, r.oid AS reader, r.rolname
    FROM pg_roles r CROSS JOIN LATERAL (
      SELECT format('%I.%I', n.nspname, c.relname) AS object, format('TABLE %s', format('%I.%I', n.nspname, c.relname)) AS target, c.oid AS relid, x.attnum, x.privilege_type,
             CASE WHEN x.col IS NULL THEN x.privilege_type ELSE format('%s (%I)', x.privilege_type, x.col) END AS privilege,
             x.grantee, x.grantor, c.relowner AS owner, x.col IS NOT NULL AS on_column, x.own_acl, x.lender_acl
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace CROSS JOIN LATERAL (
        SELECT NULL::name AS col, 0 AS attnum, a.grantee, a.grantor, a.privilege_type, '{}'::aclitem[] AS initial,
          c.relacl AS own_acl, c.relacl AS lender_acl FROM aclexplode(c.relacl) a
        UNION ALL SELECT att.attname, att.attnum, a.grantee, a.grantor, a.privilege_type, coalesce((SELECT ip.initprivs FROM pg_init_privs ip WHERE ip.classoid = 'pg_class'::regclass AND ip.objoid = c.oid AND ip.objsubid = att.attnum), '{}'),
          c.relacl || att.attacl, att.attacl FROM pg_attribute att CROSS JOIN LATERAL aclexplode(att.attacl) a WHERE att.attrelid = c.oid AND att.attnum > 0 AND NOT att.attisdropped
      ) x
      WHERE n.nspname IN ('pg_catalog', 'information_schema', 'pg_toast') AND x.grantee IN (0, r.oid)
        AND NOT EXISTS (SELECT 1 FROM aclexplode(x.initial || coalesce((SELECT ip.initprivs FROM pg_init_privs ip WHERE ip.classoid = 'pg_class'::regclass AND ip.objoid = c.oid AND ip.objsubid = 0),
              CASE WHEN n.nspname = 'information_schema' AND c.relname NOT LIKE '\_pg\_%' THEN acldefault('r', c.relowner) || makeaclitem(0, c.relowner, 'SELECT', false) ELSE acldefault('r', c.relowner) END)) b
          WHERE b.grantee IN (x.grantee, 0) AND b.privilege_type = x.privilege_type)
      UNION ALL SELECT format('%I.%I(%s)', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid)), format('ROUTINE %s', format('%I.%I(%s)', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid))), NULL::oid, 0, a.privilege_type, a.privilege_type, a.grantee, a.grantor, p.proowner, false,
        p.proacl, p.proacl
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace CROSS JOIN LATERAL aclexplode(p.proacl) a
      WHERE n.nspname IN ('pg_catalog', 'information_schema', 'pg_toast') AND a.grantee IN (0, r.oid)
        AND NOT EXISTS (SELECT 1 FROM aclexplode(coalesce((SELECT ip.initprivs FROM pg_init_privs ip WHERE ip.classoid = 'pg_proc'::regclass AND ip.objoid = p.oid AND ip.objsubid = 0), acldefault('f', p.proowner))) b
          WHERE b.grantee IN (a.grantee, 0) AND b.privilege_type = a.privilege_type)
      UNION ALL SELECT format('%I', n.nspname), format('SCHEMA %I', n.nspname), NULL::oid, 0, a.privilege_type, a.privilege_type, a.grantee, a.grantor, n.nspowner, false,
        n.nspacl, n.nspacl
      FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a
      WHERE n.nspname IN ('pg_catalog', 'information_schema', 'pg_toast') AND a.grantee IN (0, r.oid)
        AND NOT EXISTS (SELECT 1 FROM aclexplode(coalesce((SELECT ip.initprivs FROM pg_init_privs ip WHERE ip.classoid = 'pg_namespace'::regclass AND ip.objoid = n.oid AND ip.objsubid = 0),
              CASE WHEN n.nspname = 'information_schema' THEN acldefault('n', n.nspowner) || makeaclitem(0, n.nspowner, 'USAGE', false) ELSE acldefault('n', n.nspowner) END)) b
          WHERE b.grantee IN (a.grantee, 0) AND b.privilege_type = a.privilege_type)
    ) ce CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(ce.lender_acl) h WHERE h.privilege_type = ce.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, ce.grantor, ce.owner, r.oid) AND pg_has_role(ce.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), ce.owner) AS lender) b
    WHERE r.rolname = 'redacted_reader')
  SELECT (SELECT string_agg(DISTINCT e.object COLLATE "C", ', ' ORDER BY e.object COLLATE "C") FROM e),
         (SELECT CASE WHEN bool_and(pg_has_role(CASE WHEN e.owner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE e.owner END, 'USAGE')) IS NOT FALSE THEN NULL WHEN count(DISTINCT CASE WHEN e.owner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE e.owner END) = 1 THEN format(' -- run as %s or a superuser', min(CASE WHEN e.owner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE e.owner END)::regrole) ELSE ' -- run as a superuser' END FROM e),
         (SELECT string_agg(f.fix, ' ' ORDER BY f.object COLLATE "C", f.grantor <> f.reader, f.grantor) FROM (
    SELECT g.object, g.grantor, g.reader,
           concat((SELECT string_agg(concat(CASE WHEN k.lender <> g.owner THEN format('SET ROLE %s; ', k.lender::regrole) END, format('GRANT %s ON %s TO %s WITH GRANT OPTION;', k.items, g.target, g.grantor::regrole), CASE WHEN k.lender <> g.owner THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) AS items FROM (SELECT e.attnum, e.privilege_type, e.privilege AS item, e.lender, e.held FROM e WHERE e.object = g.object AND e.grantor = g.grantor AND e.lost AND (e.grantor <> e.reader OR e.on_column)) o GROUP BY o.lender) k) || ' ', CASE WHEN g.grantor <> g.owner THEN format('SET ROLE %s; ', g.grantor::regrole) END,
                  (SELECT string_agg(format('REVOKE %s ON %s FROM %s CASCADE;', q.privileges, g.target, CASE WHEN q.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(g.rolname) END), ' ' ORDER BY q.grantee)
                   FROM (SELECT e.grantee, string_agg(e.privilege, ', ' ORDER BY e.privilege COLLATE "C") AS privileges FROM e WHERE e.object = g.object AND e.grantor = g.grantor AND (e.grantor <> e.reader OR e.on_column) GROUP BY e.grantee) q),
                  CASE WHEN g.grantor <> g.owner THEN ' RESET ROLE;' END, ' ' || (SELECT string_agg(concat(CASE WHEN k.lender <> g.owner THEN format('SET ROLE %s; ', k.lender::regrole) END, concat_ws(' ', CASE WHEN k.held IS NOT NULL THEN format('REVOKE GRANT OPTION FOR %s ON %s FROM %s CASCADE;', k.held, g.target, g.grantor::regrole) END, CASE WHEN k.unheld IS NOT NULL THEN format('REVOKE %s ON %s FROM %s CASCADE;', k.unheld, g.target, g.grantor::regrole) END, nullif((SELECT concat_ws(' ', CASE WHEN bool_or(h.is_grantable) THEN format('GRANT %s ON %s TO %s WITH GRANT OPTION;', string_agg(format('%s (%I)', h.privilege_type, att.attname), ', ' ORDER BY att.attnum, h.privilege_type) FILTER (WHERE h.is_grantable), g.target, g.grantor::regrole) END, CASE WHEN bool_or(NOT h.is_grantable) THEN format('GRANT %s ON %s TO %s;', string_agg(format('%s (%I)', h.privilege_type, att.attname), ', ' ORDER BY att.attnum, h.privilege_type) FILTER (WHERE NOT h.is_grantable), g.target, g.grantor::regrole) END) FROM pg_attribute att CROSS JOIN LATERAL aclexplode(att.attacl) h WHERE att.attrelid = g.relid AND att.attnum > 0 AND NOT att.attisdropped AND h.grantee = g.grantor AND h.grantor = k.lender AND h.privilege_type = ANY (k.types)), '')), CASE WHEN k.lender <> g.owner THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE o.held) AS held, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE NOT o.held) AS unheld, array_agg(o.privilege_type) FILTER (WHERE o.attnum = 0) AS types FROM (SELECT e.attnum, e.privilege_type, e.privilege AS item, e.lender, e.held FROM e WHERE e.object = g.object AND e.grantor = g.grantor AND e.lost AND (e.grantor <> e.reader OR e.on_column)) o GROUP BY o.lender) k)) AS fix
    FROM (SELECT DISTINCT e.object, e.target, e.relid, e.grantor, e.owner, e.reader, e.rolname FROM e WHERE (e.grantor <> e.reader OR e.on_column)) g
  ) f)
    INTO leaks, runner, fixes;
  IF leaks IS NOT NULL THEN
