  END IF;
  SELECT string_agg(l.oid::text, ', ' ORDER BY l.oid),
         string_agg(concat_ws(' ', (SELECT string_agg(format('%sSET ROLE %s; %s RESET ROLE;%s', (SELECT string_agg(concat(CASE WHEN k.lender <> l.lomowner THEN format('SET ROLE %s; ', k.lender::regrole) END, format('GRANT %s ON %s TO %s WITH GRANT OPTION;', k.items, format('LARGE OBJECT %s', l.oid), t.grantor::regrole), CASE WHEN k.lender <> l.lomowner THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) AS items FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(l.lomacl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(l.lomacl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(l.lomacl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, l.lomowner, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), l.lomowner) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SELECT', 'UPDATE') AND NOT EXISTS (SELECT 1 FROM aclexplode(l.lomacl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k) || ' ', t.grantor::regrole, CASE WHEN t.grantor <> r.oid THEN (SELECT format('REVOKE %s ON %s FROM %s CASCADE;', string_agg(DISTINCT x.privilege_type, ', ' ORDER BY x.privilege_type), format('LARGE OBJECT %s', l.oid), t.grantees) FROM aclexplode(l.lomacl) x WHERE x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SELECT', 'UPDATE') HAVING count(*) > 0) END, ' ' || (SELECT string_agg(concat(CASE WHEN k.lender <> l.lomowner THEN format('SET ROLE %s; ', k.lender::regrole) END, concat_ws(' ', CASE WHEN k.held IS NOT NULL THEN format('REVOKE GRANT OPTION FOR %s ON %s FROM %s CASCADE;', k.held, format('LARGE OBJECT %s', l.oid), t.grantor::regrole) END, CASE WHEN k.unheld IS NOT NULL THEN format('REVOKE %s ON %s FROM %s CASCADE;', k.unheld, format('LARGE OBJECT %s', l.oid), t.grantor::regrole) END), CASE WHEN k.lender <> l.lomowner THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE o.held) AS held, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE NOT o.held) AS unheld FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(l.lomacl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(l.lomacl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(l.lomacl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, l.lomowner, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), l.lomowner) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SELECT', 'UPDATE') AND NOT EXISTS (SELECT 1 FROM aclexplode(l.lomacl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k)), ' ' ORDER BY t.grantor) FROM (SELECT g.grantor, string_agg(CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END, ', ' ORDER BY g.grantee) AS grantees FROM (SELECT DISTINCT a.grantor, a.grantee FROM aclexplode(l.lomacl) a WHERE a.privilege_type IN ('SELECT', 'UPDATE') AND a.grantee IN (0, r.oid) AND a.grantor <> l.lomowner AND a.grantor <> r.oid) g GROUP BY g.grantor) t), 'REVOKE ' || format('ALL ON LARGE OBJECT %s', l.oid) || ' FROM ' || nullif(concat_ws(', ', CASE WHEN EXISTS (SELECT 1 FROM aclexplode(l.lomacl) a WHERE a.privilege_type IN ('SELECT', 'UPDATE') AND a.grantee = 0 AND a.grantor = l.lomowner) THEN 'PUBLIC' END, CASE WHEN r.oid = l.lomowner OR EXISTS (SELECT 1 FROM aclexplode(l.lomacl) a WHERE a.privilege_type IN ('SELECT', 'UPDATE') AND a.grantee = r.oid AND a.grantor = l.lomowner) THEN quote_ident(r.rolname) END), '') || ' CASCADE;'), ' ' ORDER BY l.oid),
         CASE WHEN bool_and(pg_has_role(CASE WHEN l.lomowner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE l.lomowner END, 'USAGE')) IS NOT FALSE THEN NULL WHEN count(DISTINCT CASE WHEN l.lomowner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE l.lomowner END) = 1 THEN format(' -- run as %s or a superuser', min(CASE WHEN l.lomowner = to_regrole('pg_database_owner')::oid THEN (SELECT dbo.datdba FROM pg_database dbo WHERE dbo.datname = current_database()) ELSE l.lomowner END)::regrole) ELSE ' -- run as a superuser' END
    INTO leaks, fixes, runner
  FROM pg_largeobject_metadata l CROSS JOIN pg_roles r
  WHERE r.rolname = 'redacted_reader'
    AND l.lomowner <> r.oid
    AND EXISTS (SELECT 1 FROM aclexplode(l.lomacl) a WHERE a.grantee IN (0, r.oid));
  IF leaks IS NOT NULL THEN
    RAISE EXCEPTION 'hyde-db: role redacted_reader can read large objects it does not own: %. Fix: %', leaks, concat(CASE WHEN fixes LIKE '%; %' AND fixes NOT LIKE 'ALTER SYSTEM %' THEN 'BEGIN; ' || fixes || ' COMMIT;' ELSE fixes END, CASE WHEN fixes LIKE '%SET ROLE %' THEN ' -- run as a superuser' ELSE runner END);
  END IF;
  IF current_setting('server_version_num')::int >= 150000 THEN
    EXECUTE $p$SELECT string_agg(format('%I', pa.parname), ', ' ORDER BY pa.parname),
             string_agg(concat_ws(' ', (SELECT string_agg(format('%sSET ROLE %s; %s RESET ROLE;%s', (SELECT string_agg(concat(CASE WHEN k.lender <> 10::oid THEN format('SET ROLE %s; ', k.lender::regrole) END, format('GRANT %s ON %s TO %s WITH GRANT OPTION;', k.items, format('PARAMETER %I', pa.parname), t.grantor::regrole), CASE WHEN k.lender <> 10::oid THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) AS items FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(pa.paracl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(pa.paracl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(pa.paracl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, 10::oid, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), 10::oid) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SET', 'ALTER SYSTEM') AND NOT EXISTS (SELECT 1 FROM aclexplode(pa.paracl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k) || ' ', t.grantor::regrole, CASE WHEN t.grantor <> r.oid THEN (SELECT format('REVOKE %s ON %s FROM %s CASCADE;', string_agg(DISTINCT x.privilege_type, ', ' ORDER BY x.privilege_type), format('PARAMETER %I', pa.parname), t.grantees) FROM aclexplode(pa.paracl) x WHERE x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SET', 'ALTER SYSTEM') HAVING count(*) > 0) END, ' ' || (SELECT string_agg(concat(CASE WHEN k.lender <> 10::oid THEN format('SET ROLE %s; ', k.lender::regrole) END, concat_ws(' ', CASE WHEN k.held IS NOT NULL THEN format('REVOKE GRANT OPTION FOR %s ON %s FROM %s CASCADE;', k.held, format('PARAMETER %I', pa.parname), t.grantor::regrole) END, CASE WHEN k.unheld IS NOT NULL THEN format('REVOKE %s ON %s FROM %s CASCADE;', k.unheld, format('PARAMETER %I', pa.parname), t.grantor::regrole) END), CASE WHEN k.lender <> 10::oid THEN ' RESET ROLE;' END), ' ' ORDER BY k.lender) FROM (SELECT o.lender, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE o.held) AS held, string_agg(o.item, ', ' ORDER BY o.attnum, o.privilege_type) FILTER (WHERE NOT o.held) AS unheld FROM (SELECT 0 AS attnum, x.privilege_type, x.privilege_type AS item, b.lender, EXISTS (SELECT 1 FROM aclexplode(pa.paracl) h WHERE h.grantee = t.grantor AND h.grantor = b.lender AND h.privilege_type = x.privilege_type) AS held FROM aclexplode(pa.paracl) x CROSS JOIN LATERAL (SELECT coalesce((SELECT min(h.grantee) FROM aclexplode(pa.paracl) h WHERE h.privilege_type = x.privilege_type AND h.is_grantable AND h.grantee NOT IN (0, t.grantor, 10::oid, r.oid) AND pg_has_role(t.grantor, h.grantee, 'USAGE') AND NOT EXISTS (SELECT 1 FROM pg_roles s WHERE s.oid = h.grantee AND s.rolsuper)), 10::oid) AS lender) b WHERE t.grantor <> r.oid AND x.grantor = t.grantor AND x.grantee IN (0, r.oid) AND x.privilege_type IN ('SET', 'ALTER SYSTEM') AND NOT EXISTS (SELECT 1 FROM aclexplode(pa.paracl) h WHERE h.grantee = t.grantor AND h.privilege_type = x.privilege_type AND h.is_grantable)) o GROUP BY o.lender) k)), ' ' ORDER BY t.grantor) FROM (SELECT g.grantor, string_agg(CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END, ', ' ORDER BY g.grantee) AS grantees FROM (SELECT DISTINCT a.grantor, a.grantee FROM aclexplode(pa.paracl) a WHERE a.privilege_type IN ('SET', 'ALTER SYSTEM') AND a.grantee IN (0, r.oid) AND a.grantor <> 10::oid AND a.grantor <> r.oid) g GROUP BY g.grantor) t), 'REVOKE ' || format('%s ON PARAMETER %I', (SELECT string_agg(DISTINCT a.privilege_type, ', ' ORDER BY a.privilege_type) FROM aclexplode(pa.paracl) a WHERE a.grantee IN (0, r.oid) AND a.grantor = 10::oid), pa.parname) || ' FROM ' || nullif(concat_ws(', ', CASE WHEN EXISTS (SELECT 1 FROM aclexplode(pa.paracl) a WHERE a.privilege_type IN ('SET', 'ALTER SYSTEM') AND a.grantee = 0 AND a.grantor = 10::oid) THEN 'PUBLIC' END, CASE WHEN r.oid = 10::oid OR EXISTS (SELECT 1 FROM aclexplode(pa.paracl) a WHERE a.privilege_type IN ('SET', 'ALTER SYSTEM') AND a.grantee = r.oid AND a.grantor = 10::oid) THEN quote_ident(r.rolname) END), '') || ' CASCADE;'), ' ' ORDER BY pa.parname)
      FROM pg_parameter_acl pa CROSS JOIN pg_roles r
      WHERE r.rolname = 'redacted_reader'
        AND EXISTS (SELECT 1 FROM aclexplode(pa.paracl) a WHERE a.grantee IN (0, r.oid))$p$
      INTO leaks, fixes;
    IF leaks IS NOT NULL THEN
      RAISE EXCEPTION 'hyde-db: role redacted_reader has privileges on configuration parameters: %. Fix: %', leaks, concat(CASE WHEN fixes LIKE '%; %' AND fixes NOT LIKE 'ALTER SYSTEM %' THEN 'BEGIN; ' || fixes || ' COMMIT;' ELSE fixes END, ' -- run as a superuser');
    END IF;
  END IF;
END $$;

COMMIT;
